#include <stdio.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) { return (*(int*)a - *(int*)b); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *arr = (int*)malloc(2 * n * sizeof(int));
    for (int i = 0; i < 2 * n; i++) scanf("%d", &arr[i]);
    qsort(arr, 2 * n, sizeof(int), cmp);
    double mid = (arr[n - 1] + arr[n]) / 2.0;
    if (mid == (long long)mid) printf("%lld\n", (long long)mid);
    else printf("%.1f\n", mid);
    free(arr);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(2 * n);
        for (int i = 0; i < 2 * n; i++) cin >> a[i];
        sort(a.begin(), a.end());
        double mid = (a[n - 1] + a[n]) / 2.0;
        if (mid == (long long)mid) cout << (long long)mid << "\n";
        else cout << mid << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] a = new int[2 * n];
            for (int i = 0; i < 2 * n; i++) a[i] = sc.nextInt();
            Arrays.sort(a);
            double mid = (a[n - 1] + a[n]) / 2.0;
            if (mid == (long)mid) System.out.println((long)mid);
            else System.out.println(mid);
        }
    }
}

