const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const a = toks.slice(1, 1 + 2 * n).sort((x, y) => x - y);
        const mid = (a[n - 1] + a[n]) / 2;
        console.log(Number.isInteger(mid) ? mid.toString() : mid.toString());
    }
}
main();

